    @pytest.mark.asyncio
    async def test_ontUpgrade(self):
        for index in range(ontCount):
            exeOntInfo = [ontSlotIDList[index], ontPortIDList[index], ontOntIDList[index]]
            exeOntModel = ontModelList[index]
            self.driver.find_element(By.LINK_TEXT, "Maintenance").click()
            time.sleep(3)
            self.driver.find_element(By.LINK_TEXT, "Schedule").click()
            self.driver.find_element(By.CSS_SELECTOR, "#i_action_create_collector > a").click()
            self.driver.find_element(By.ID, "schedule_type").click()
            Select(self.driver.find_element(By.ID, "schedule_type")).select_by_visible_text("ONT firmware upgrade")
            self.driver.find_element(By.ID, "ont_firmware_schedule_name").click()
            self.driver.find_element(By.ID, "ont_firmware_schedule_name").send_keys("$pyE2E_ontUpgrade_" + str(index+1))
            self.driver.find_element(By.ID, "maintain_ont_fw_upgrade_selectfile").click()
            Select(self.driver.find_element(By.ID, "maintain_ont_fw_upgrade_selectfile")).select_by_visible_text("Local")
            self.driver.find_element(By.ID, "loadfile").click()
            self.driver.find_element(By.ID, "load").send_keys(uploadPath + ontFwList[index])
            self.driver.find_element(By.ID, "ont_fw_upgrade_ftp").click()
            self.driver.find_element(By.ID, "ont_fw_upgrade_ftp").send_keys(Keys.CONTROL + "a")
            self.driver.find_element(By.ID, "ont_fw_upgrade_ftp").send_keys(Keys.DELETE)
            self.driver.find_element(By.ID, "ont_fw_upgrade_ftp").send_keys("180")
            self.driver.find_element(By.ID, "ont_fw_upgrade_starttime").click()
            testTime = (datetime.now() + timedelta(seconds = 5))
            scheduleTime = testTime.strftime(dateFormat)
            scheduleTimeStart = testTime.strftime("%H:%M:%S")
            self.driver.find_element(By.ID, "ont_fw_upgrade_starttime").click()
            self.driver.find_element(By.ID, "ont_fw_upgrade_starttime").clear()
            self.driver.find_element(By.ID, "ont_fw_upgrade_starttime").send_keys(scheduleTimeStart)
            self.driver.find_element(By.CSS_SELECTOR, ".ui-datepicker-close").click()
            self.driver.find_element(By.ID, "ont_fw_upgrade_endtime").click()
            scheduleTimeEnd = (testTime + timedelta(minutes = 40)).strftime("%H:%M:%S")
            self.driver.find_element(By.ID, "ont_fw_upgrade_endtime").clear()
            self.driver.find_element(By.ID, "ont_fw_upgrade_endtime").send_keys(scheduleTimeEnd)
            self.driver.find_element(By.CSS_SELECTOR, ".ui-datepicker-close").click()
            self.driver.find_element(By.XPATH, "//label[contains(.,\'Reboot ONT after successful firmware upgrade\')]").click()
            self.driver.find_element(By.XPATH, "//label[contains(.,\'Upgrade matched ONT model\')]").click()
            Select(self.driver.find_element(By.ID, "ont_fw_upgrade_mode")).select_by_visible_text(exeOntModel)
            self.driver.find_element(By.ID, "add_row").click()
            self.driver.find_element(By.XPATH, "//label[contains(.,\'" + dutNodeName + "\')]").location_once_scrolled_into_view
            self.driver.find_element(By.XPATH, "//label[contains(.,\'" + dutNodeName + "\')]").click()
            self.driver.find_element(By.XPATH, "//input[@value=\'Search ONT\']").click()
            time.sleep(3)
            clickBySlotPortOnt(self, dutName, exeOntInfo[0], exeOntInfo[1], exeOntInfo[2])
            self.driver.find_element(By.XPATH, "//input[@value=\'Add\']").click()
            self.driver.find_element(By.XPATH, "//input[@value=\'Save\']").click()
            time.sleep(5)
            entryPosition = getPositionByCol(self, "schedule_table", "ScheduleTime", scheduleTime)
            waitScheduleSuccess (self, entryPosition)
            getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").click()
            time.sleep(3)
            #Maintanence table detail 1 assert
            with assume: assert getScheduleResultByCol (self, "Index") == "1"
            with assume: assert getScheduleResultByCol (self, "Schedule Name") == "$pyE2E_ontUpgrade_" + str(index+1)
            scheduleTime = getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleTime").text
            minTime = datetime.strptime(scheduleTime, dateFormat)
            maxTime = minTime + timedelta(seconds = 600)
            with assume: assert minTime <= datetime.strptime(getScheduleResultByCol (self, "Execute Time"), dateFormat) <= maxTime
            resultSummary = getScheduleResultByCol (self, "Result Summary")
            resultSummaryList = resultSummary.split(",")
            resultSummaryList = [re.sub(r"^.*:", "", i,flags = re.DOTALL) for i in resultSummaryList]
            with assume: assert int(resultSummaryList[0]) >= 0
            with assume: assert int(resultSummaryList[1]) == 0
            #Maintanence table detail 2 assert
            detailScheduleNameList = getScheduleResultDetailListByCol (self, "ScheduleName")
            detailExecuteDateList = getScheduleResultDetailListByCol (self, "Date")
            detailDeviceNameList = getScheduleResultDetailListByCol (self, "DeviceName")
            detailSlotList = getScheduleResultDetailListByCol (self, "SlotID")
            detailPortList = getScheduleResultDetailListByCol (self, "PortID")
            detailONTList = getScheduleResultDetailListByCol (self, "OntID")
            detailResultList = getScheduleResultDetailListByCol (self, "Result ")
            detailCauseList = getScheduleResultDetailListByCol (self, "Cause ")
            with assume: assert checkAllElementInListAre (detailScheduleNameList, "$pyE2E_ontUpgrade_" + str(index+1))
            with assume: assert checkAllElementInListPartialMatch (detailExecuteDateList, scheduleTime)
            with assume: assert checkAllElementInListAre (detailDeviceNameList, dutName)
            with assume: assert detailSlotList == [exeOntInfo[0]]
            with assume: assert detailPortList == [exeOntInfo[1]]
            with assume: assert detailONTList == [exeOntInfo[2]]
            with assume: assert checkAllElementInListAre (detailResultList, "Success")
            with assume: assert checkAllElementInListPartialMatch (detailCauseList, "Success")
